import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"31、【鹹】 艮下兌上","description":"周易口訣義 - 31、【鹹】 艮下兌上","frontmatter":{"title":"31、【鹹】 艮下兌上","description":"周易口訣義 - 31、【鹹】 艮下兌上"},"headers":[],"relativePath":"classics/koujueyi/033.md","filePath":"classics/koujueyi/033.md"}'),r={name:"classics/koujueyi/033.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_31、【鹹】-艮下兌上" tabindex="-1">31、【鹹】 艮下兌上 <a class="header-anchor" href="#_31、【鹹】-艮下兌上" aria-label="Permalink to “31、【鹹】 艮下兌上”">​</a></h1><p>彖曰：鹹，感也。柔上而剛下，二氣感應以相與，止而說，男下女，是以亨利貞，取女吉也。天地感而萬物化生，聖人感人心而天下和平，觀其所感，而天地萬物之情可見矣！</p><p>象曰：山上有澤，鹹。君子以虛受人。</p><p>初六：鹹其拇。</p><p>象曰：「鹹其拇」，志在外也。</p><p>六二：鹹其腓，兇，居吉。</p><p>象曰：雖兇居吉，順不害也。</p><p>九三，鹹其股，執其隨，往吝。</p><p>象曰：「鹹其股」，亦不處也，志在隨人，所執下也。</p><p>九四，貞吉，悔亡。憧憧往來，朋從爾思。</p><p>象曰：「貞吉悔亡」，未感害也。「憧憧往來」，未光大也。</p><p>九五，鹹其脢，無悔。</p><p>象曰：「鹹其脢」，志末也。</p><p>上六，鹹其輔頰舌。</p><p>象曰：「鹹其輔頰、舌」，滕口說也。</p><p>解讀</p><p>「鹹，亨，利貞」者，鹹，感也，感，應也，以二氣交感，所以亨通，感應之道，必須以正，故曰「利貞」也。「取女吉」者，以艮、兌俱是少，相配交感，感而又正，備禮乃行，即是婚取之善也。象曰「山上有澤，鹹」者，山體空虛，艮陽澤性潤下，兌陰山受澤潤，萬物以生，是相感之象也。君子以虛受人者，夫欲感人之心，懷來萬邦者，必須空虛其心，受納諸物，無所棄遺。何妥雲：「虛心受人，不閒不拒，即物來歸己，君子之志也。」</p><p>「初六，鹹其拇」者，「拇」是足大指，初六處感之始而應於四，喻體之中，在於足指，相感微淺，故無吉凶悔吝也。</p><p>「六二，鹹其腓，兇，居吉」者，「腓」，膊腸也。腓體動躁，或屈或伸，不能安靜。若以躁感物，必致兇災；若靜而相感，即懷吉慶。故曰「鹹其腓，兇，居吉」。</p><p>「九三，鹹其股，執其隨，往吝」者，「股」，腿髀也；「隨」謂足。九三漸進於腿髀之間。股之為體，動靜不能自處，常執隨其足。股非動躁之物，而強抑其情。譬之於人，自無特操，卓然獨處，而乃隨從於人，是所執卑劣。以斯而行，必招恨辱，故曰「往吝」也。</p><p>「九四，貞吉，悔亡。憧憧往來，朋從爾思」者，以陽居陰，邪僻相感，患必生焉，故須貞正獲吉，憂悔乃亡，故云「貞吉，悔亡」也。「憧憧」，往來之貌。夫相感之道，固當修德，安處其位，使物自來，即朋黨從爾所思，斯未為光大，故小象雲「未光大也」。</p><p>「九五，鹹其脢，無悔」者，「脢」，背脊也。夫感應之道，貴乎心實。今九五所感在於「脢」，明其非在衷心，薄於交義，故但「無悔」而已。「脢」亦心之上，口之下也。</p><p>上六：鹹其輔頰舌。輔頰是言語之具，上六鹹道之末，所感在於口舌頰頷之間，不能以心相感，但滕達口舌傳說而已，故小象雲「滕口說」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
